    def on_flow_retry_failed_clicked(self):
        """Chạy lại các file lỗi trong batch - Giống Whisk: kiểm tra từ table và hiển thị dialog cookie"""
        # ✅ Kiểm tra failed files từ table (giống Whisk)
        failed_files_from_table = self._check_flow_failed_files_from_table()
        
        if not failed_files_from_table:
            QMessageBox.information(self, "Không có file lỗi", "Không có file nào bị lỗi để chạy lại.")
            return
        
        if self.flow_is_running or self.flow_batch_active:
            QMessageBox.information(self, "Flow đang chạy", "Đang có một lượt tạo ảnh Flow khác, vui lòng đợi hoàn tất.")
            return
        
        # ✅ Hiển thị dialog cookie chính (giống nút cài đặt cookie) trước khi retry
        self.show_cookie_dialog()
        
        # ✅ Kiểm tra cookies sau khi đóng dialog
        if not (self.cookie_value or self.cookies_list):
            self.log("⚠️ Người dùng không nhập cookie, dừng retry")
            QMessageBox.warning(self, "Cảnh báo", "Vui lòng nhập cookie trước khi retry!")
            return
        
        # ✅ Cập nhật flow_failed_files từ table để đảm bảo đồng bộ
        self.flow_failed_files = failed_files_from_table
        
        # ✅ LOGIC MỚI: Thu thập TẤT CẢ failed jobs từ các file lỗi
        all_failed_jobs = []
        file_to_jobs_mapping = {}  # {file_stem: [failed_jobs]}
        
        for file_path in self.flow_failed_files:
            failed_jobs = self._get_failed_jobs_for_file(file_path)
            if failed_jobs:
                file_stem = file_path.stem
                file_to_jobs_mapping[file_stem] = failed_jobs
                all_failed_jobs.extend(failed_jobs)
        
        if not all_failed_jobs:
            QMessageBox.information(self, "Không có prompt lỗi", "Không có prompt nào bị lỗi để chạy lại.")
            return
        
        # Lấy params từ batch params hoặc UI
        model_code = self.flow_model_combo.currentData() if hasattr(self, "flow_model_combo") else "GEM_PIX_2"
        aspect_ratio = self.flow_aspect_combo.currentData() if hasattr(self, "flow_aspect_combo") else "IMAGE_ASPECT_RATIO_LANDSCAPE"
        reference_paths = list(self.flow_reference_paths)
        
        # ✅ Disable buttons ngay
        self._flow_enable_run_button(False)
        if hasattr(self, "btn_flow_retry_failed"):
            self.btn_flow_retry_failed.setEnabled(False)
        
        # ✅ Update status của các file lỗi trong batch table
        for file_path in self.flow_failed_files:
            self._update_flow_batch_status(file_path, "Đang chạy lại…")
        
        total_failed = len(all_failed_jobs)
        self._flow_update_status_text(f"Đang chạy lại {total_failed} prompt lỗi…")
        self._flow_update_hint_text("Chỉ chạy lại các prompt bị lỗi, giữ nguyên vị trí lưu.")
        self.log(f"🔄 Flow retry: {total_failed} prompt(s) lỗi từ {len(self.flow_failed_files)} file(s)")
        
        # ✅ Chạy retry trong worker thread riêng
        self.flow_is_running = True
        self.flow_batch_active = True
        
        # Lưu thông tin để dùng trong worker
        retry_context = {
            "all_failed_jobs": all_failed_jobs,
            "file_to_jobs_mapping": file_to_jobs_mapping,
            "failed_files": list(self.flow_failed_files),
            "model_code": model_code,
            "aspect_ratio": aspect_ratio,
            "reference_paths": reference_paths,
        }
        
        worker = threading.Thread(
            target=self._flow_retry_failed_worker,
            args=(retry_context,),
            daemon=True,
        )
        worker.start()

    
