        preview.setWordWrap(True)
        preview.setMinimumSize(180, 120)
        preview.setStyleSheet("""
            QLabel {
                background: #f8fafc;
                border: 1px dashed #cbd5e1;
                border-radius: 12px;
                color: #64748b;
                font-size: 12px;
                padding: 8px;
            }
        """)
