    def show_review_menu(self, task_index, button):
        """Mở video trực tiếp nếu đã tải về, hoặc hiển thị menu nếu có nhiều video"""
        from PySide6.QtWidgets import QMenu
        from PySide6.QtCore import QPoint
        
        # Get video paths for this task
        video_paths = self.task_video_paths.get(task_index, [])
        
        if not video_paths:
            self.log(f"⚠️ Chưa có video cho task #{task_index}")
            return
        
        # ✅ Nếu chỉ có 1 video và đã tải về → mở trực tiếp
        if len(video_paths) == 1:
            video_path = video_paths[0]
            video_file = Path(video_path)
            if video_file.exists():
                # Kiểm tra file size (phải > 100KB)
                try:
                    file_size = video_file.stat().st_size
                    if file_size >= 100 * 1024:  # >= 100KB
                        self.open_video(video_path)
                        return
                except Exception:
                    pass
        
        # ✅ Nếu có nhiều video hoặc chưa tải về → hiển thị menu
        # Create menu với style gọn gàng
        menu = QMenu(self)
        menu.setStyleSheet("""
            QMenu {
                background-color: white;
                border: 1px solid #BDBDBD;
                border-radius: 4px;
                padding: 4px;
            }
            QMenu::item {
                background-color: transparent;
                color: #333333;
                padding: 6px 20px;
                margin: 2px 4px;
                border-radius: 3px;
            }
            QMenu::item:selected {
                background-color: #E3F2FD;
                color: #1976D2;
            }
            QMenu::item:pressed {
                background-color: #BBDEFB;
            }
        """)
        
        # Add actions với icon
        for i, video_path in enumerate(video_paths, 1):
            action = menu.addAction(f"▶ v{i}")
            action.triggered.connect(lambda checked, path=video_path: self.open_video(path))
        
        # ✅ Show menu ngay cạnh button - Vị trí chính xác, luôn nằm cạnh nút Xem
        # Lấy vị trí góc dưới bên phải của button trong tọa độ global
        button_rect = button.geometry()
        button_bottom_right = button.mapToGlobal(QPoint(button_rect.width(), button_rect.height()))
        
        # Hiện menu ngay cạnh bên phải button, căn trên với button
        menu_pos = QPoint(button_bottom_right.x() + 5, button_bottom_right.y() - button_rect.height())
        
        # ✅ Đảm bảo menu không bị tràn ra ngoài màn hình
        screen = QApplication.primaryScreen().availableGeometry()
        
        # Ước tính kích thước menu (mỗi item ~30px height, width ~150px)
        estimated_menu_width = 150
        estimated_menu_height = len(video_paths) * 30 + 10  # padding
        
        # Nếu menu bị tràn bên phải → hiện bên trái button
        if menu_pos.x() + estimated_menu_width > screen.right():
            menu_pos.setX(button_bottom_right.x() - estimated_menu_width - 5)
        
        # Nếu menu bị tràn phía dưới → hiện phía trên button
        if menu_pos.y() + estimated_menu_height > screen.bottom():
            menu_pos.setY(button_bottom_right.y() - estimated_menu_height - 5)
        
        # Đảm bảo không bị tràn bên trái
        if menu_pos.x() < screen.left():
            menu_pos.setX(screen.left() + 5)
        
        # Đảm bảo không bị tràn phía trên
        if menu_pos.y() < screen.top():
            menu_pos.setY(screen.top() + 5)
        
        # Hiển thị menu tại vị trí đã tính toán
        menu.exec(menu_pos)

    def _update_task_metadata_cache(self, tasks=None, reset=False):
        """Snapshot task metadata for retry flows (integrate, custom modes, etc.)."""
        try:
            if reset or not hasattr(self, "task_retry_metadata"):
                self.task_retry_metadata = {}
            task_list = tasks if tasks is not None else getattr(self, "current_tasks", [])
            if not task_list:
                return
            for task in task_list:
                if not task:
                    continue
                index = getattr(task, "prompt_index", None)
                if index is None:
                    index = getattr(task, "task_index", None)
                if not index:
                    continue
                meta = {
                    "prompt_text": getattr(task, "prompt_text", ""),
                    "output_folder": getattr(task, "output_folder", None),
                    "source_file": getattr(task, "source_file", None),
                    "local_index": getattr(task, "local_index", None),
                    "integrate_images": list(getattr(task, "integrate_images", []) or []),
                    "is_custom_integrate": getattr(task, "is_custom_integrate", False),
                    "image_path": getattr(task, "image_path", None),
                    "end_image_path": getattr(task, "end_image_path", None),
                }
                self.task_retry_metadata[index] = meta
        except Exception as e:
            print(f"[TASK CACHE] Failed to snapshot metadata: {e}")

    def _restore_task_metadata_from_cache(self, task):
        """Restore cached metadata (integrate images, source_file, etc.) for rebuilt tasks."""
        index = None
        try:
            if not task or not hasattr(self, "task_retry_metadata"):
                return
            index = getattr(task, "prompt_index", None)
            if index is None:
                index = getattr(task, "task_index", None)
            if not index:
                return
            meta = self.task_retry_metadata.get(index)
            if not meta:
                return
            if meta.get("output_folder") and not getattr(task, "output_folder", None):
                task.output_folder = meta["output_folder"]
            if meta.get("source_file") and not getattr(task, "source_file", None):
                task.source_file = meta["source_file"]
            if meta.get("local_index") and not getattr(task, "local_index", None):
                task.local_index = meta["local_index"]
            if meta.get("integrate_images"):
                task.integrate_images = list(meta["integrate_images"])
            if "is_custom_integrate" in meta:
                task.is_custom_integrate = meta["is_custom_integrate"]
            if meta.get("image_path") and not getattr(task, "image_path", None):
                task.image_path = meta["image_path"]
            if meta.get("end_image_path") and not getattr(task, "end_image_path", None):
                task.end_image_path = meta["end_image_path"]
        except Exception as e:
            label = index if index is not None else "?"
            print(f"[TASK CACHE] Failed to restore metadata for task #{label}: {e}")


