    @Slot(int, str)
    def update_image_row_status_slot(self, index, status):
        """SLOT: Update image row status - runs in main thread"""
        try:
            row = index - 1
            if row < self.image_results_table.rowCount():
                self.image_results_table.setItem(row, 1, QTableWidgetItem(status))
                
                # ✅ Update card khi status thay đổi
                if index in self.image_widgets:
                    # Get prompt from table
                    prompt_item = self.image_results_table.item(row, 0)
                    prompt = prompt_item.data(Qt.UserRole) or prompt_item.text() if prompt_item else ""
                    
                    # Get image path from table
                    path_item = self.image_results_table.item(row, 2)
                    image_path = path_item.text() if path_item else ""
                    
                    # Get num_images để tính progress_total
                    num_images = self.spin_num_images.value()
                    progress_current = 0
                    progress_total = num_images
                    
                    # Nếu status là "Hoàn thành", progress = total
                    if status == "Hoàn thành" or status == "✅ Hoàn thành":
                        progress_current = progress_total
                    
                    # Update card
                    self.add_image_to_grid(index, prompt, status, image_path, progress_current, progress_total)
                
                # ✅ Enable nút "Retry All Lỗi" ngay khi có prompt bị fail (giống flow tab)
                if hasattr(self, "btn_image_retry_all"):
                    has_failed = self._check_image_failed_from_table()
                    self.btn_image_retry_all.setEnabled(has_failed)
        except Exception as e:
            print(f"❌ Exception in update_image_row_status_slot: {e}")

    def _check_image_failed_from_table(self):
        """Kiểm tra failed images từ image results table (giống flow tab) - trả về True nếu có ít nhất 1 ảnh lỗi"""
        try:
            if not hasattr(self, "image_results_table"):
                return False
            
            error_keywords = ["Lỗi", "Thất bại", "❌", "Failed", "Fail", "Error"]
            exclude_keywords = ["Hoàn thành", "Completed", "✅", "Đang tạo", "Đang xử lý", "Chờ xử lý", "Processing", "Pending"]
            
            for row in range(self.image_results_table.rowCount()):
                status_item = self.image_results_table.item(row, 1)
                if status_item:
                    status = status_item.text().strip()
                    
                    # Kiểm tra kỹ: chỉ lấy status thực sự lỗi
                    is_error = any(keyword in status for keyword in error_keywords)
                    is_not_processing = not any(keyword in status for keyword in exclude_keywords)
                    
                    if is_error and is_not_processing:
                        return True  # Có ít nhất 1 ảnh lỗi
            
            return False  # Không có ảnh nào lỗi
        except Exception as e:
            self.log(f"❌ Lỗi _check_image_failed_from_table: {e}")
            return False
    
    def update_image_row_path(self, index, file_path):
        """Update image row path - emit signal (thread-safe)"""
