    def add_expand_ref_fixed_images(self):
        """Thêm ảnh nhân vật cố định cho Expand + Reference"""
        if not hasattr(self, 'expand_ref_fixed_images_paths'):
            self.expand_ref_fixed_images_paths = []
        
        # Giới hạn tối đa 3 ảnh
        remaining = 3 - len(self.expand_ref_fixed_images_paths)
        if remaining <= 0:
            QMessageBox.warning(self, "Giới hạn", "Đã đạt tối đa 3 ảnh nhân vật cố định!")
            return
        
        file_paths, _ = QFileDialog.getOpenFileNames(
            self,
            f"Chọn ảnh nhân vật (còn {remaining} slot)",
            "",
            "Image Files (*.jpg *.jpeg *.png *.bmp *.gif *.webp);;All Files (*)"
        )
        
        if file_paths:
            for path in file_paths:
                if len(self.expand_ref_fixed_images_paths) >= 3:
                    break
                if path not in self.expand_ref_fixed_images_paths:
                    self.expand_ref_fixed_images_paths.append(path)
                    self.log(f"➕ Thêm ảnh nhân vật cố định: {Path(path).name}")
            
            self.refresh_expand_ref_fixed_images_list()
    
    def clear_expand_ref_fixed_images(self):
        """Xóa tất cả ảnh nhân vật cố định"""
        if hasattr(self, 'expand_ref_fixed_images_paths'):
            self.expand_ref_fixed_images_paths.clear()
        self.refresh_expand_ref_fixed_images_list()
        self.log("🗑️ Đã xóa tất cả ảnh nhân vật cố định")
    
    def refresh_expand_ref_fixed_images_list(self):
        """Refresh UI hiển thị danh sách ảnh nhân vật cố định"""
        if not hasattr(self, 'expand_ref_fixed_images_list'):
            return
        
        self.expand_ref_fixed_images_list.clear()
        
        if not hasattr(self, 'expand_ref_fixed_images_paths'):
            self.expand_ref_fixed_images_paths = []

        if hasattr(self, 'expand_ref_fixed_images_grid') and self.expand_ref_fixed_images_grid is not None:
            grid_paths = list(self.expand_ref_fixed_images_grid.image_paths)
            if grid_paths != list(self.expand_ref_fixed_images_paths):
                self.expand_ref_fixed_images_grid.image_paths = list(self.expand_ref_fixed_images_paths)
                self.expand_ref_fixed_images_grid._rebuild_layout()
        
        for idx, path in enumerate(self.expand_ref_fixed_images_paths, 1):
            filename = Path(path).name
            item = QListWidgetItem(f"🖼️ {idx}. {filename}")
            item.setToolTip(path)
            self.expand_ref_fixed_images_list.addItem(item)
    
