    def open_custom_integrate_dialog(self):
        """Mở/Đóng dialog cấu hình Tùy Chỉnh - Chỉ đóng/mở popup, không thay đổi text hay trạng thái"""
        try:
            # ✅ Bảo vệ nút mở popup - lưu trạng thái ban đầu
            original_text = "⚙️ Mở Cấu Hình Tùy Chỉnh"
            original_enabled = True
            if hasattr(self, 'btn_open_custom'):
                original_text = self.btn_open_custom.text()
                original_enabled = self.btn_open_custom.isEnabled()
            
            # ✅ Nếu dialog đã tồn tại và đang hiển thị, đóng nó
            if hasattr(self, '_custom_dialog') and self._custom_dialog and self._custom_dialog.isVisible():
                self._custom_dialog.close()
                # ✅ Khôi phục trạng thái ban đầu
                if hasattr(self, 'btn_open_custom'):
                    self.btn_open_custom.setEnabled(original_enabled)
                    self.btn_open_custom.setText(original_text)
                return
            
            # ✅ Nếu dialog chưa tồn tại hoặc đã đóng, mở dialog mới
            if not hasattr(self, '_custom_dialog') or not self._custom_dialog or not self._custom_dialog.isVisible():
                self._custom_dialog = CustomIntegrateDialog(self)
                self._custom_dialog.exec()
            
            # ✅ Đảm bảo nút mở popup luôn enabled và text không đổi (sau khi đóng dialog)
            if hasattr(self, 'btn_open_custom'):
                self.btn_open_custom.setEnabled(True)
                self.btn_open_custom.setText("⚙️ Mở Cấu Hình Tùy Chỉnh")
        except Exception as e:
            self.log(f"❌ Lỗi mở dialog: {e}")
            QMessageBox.critical(self, "Lỗi", f"Không thể mở dialog: {e}")
            if hasattr(self, '_custom_dialog'):
                self._custom_dialog = None
            # ✅ Đảm bảo nút mở popup luôn enabled và text không đổi (ngay cả khi có lỗi)
            if hasattr(self, 'btn_open_custom'):
                self.btn_open_custom.setEnabled(True)
                self.btn_open_custom.setText("⚙️ Mở Cấu Hình Tùy Chỉnh")
    
    def on_import_characters(self):
        """Import characters (tối đa 10 nhân vật)"""
        try:
            # Kiểm tra số lượng hiện tại
            current_count = len(self.custom_characters)
            if current_count >= 10:
                QMessageBox.warning(self, "Cảnh báo", "Đã đạt tối đa 10 nhân vật!")
                return
            
            # Cho phép chọn nhiều ảnh cùng lúc
            remaining_slots = 10 - current_count
            files, _ = QFileDialog.getOpenFileNames(
                self, 
                f"Chọn ảnh character (còn {remaining_slots} slot)", 
                "", 
                "Image Files (*.jpg *.jpeg *.png *.bmp *.gif *.webp);;All Files (*)"
            )
            
            if not files:
                return
            
            # Giới hạn số lượng
            files_to_add = files[:remaining_slots]
            
            for img_path in files_to_add:
                if current_count >= 10:
                    break
                
                # Lấy tên file (không có extension) làm tên character
                char_name = Path(img_path).stem
                
                # Nếu tên đã tồn tại, thêm số
                original_name = char_name
                counter = 1
                while char_name in self.custom_characters:
                    char_name = f"{original_name}_{counter}"
                    counter += 1
                
                # Thêm vào dictionary
                self.custom_characters[char_name] = img_path
                current_count += 1
            
            # Refresh table (và dialog nếu đang mở)
            self.refresh_characters_table()
            if hasattr(self, '_custom_dialog') and self._custom_dialog and self._custom_dialog.isVisible():
                QTimer.singleShot(0, lambda: self._custom_dialog.refresh_characters_table())
            
            self.log(f"✅ Đã import {len(files_to_add)} nhân vật (Tổng: {len(self.custom_characters)}/10)")
            
        except Exception as e:
            self.log(f"❌ Lỗi import characters: {e}")
            QMessageBox.critical(self, "Lỗi", f"Lỗi import characters: {e}")
    
    def refresh_characters_table(self):
        """Refresh characters table (chỉ nếu có table trong main window - giờ table chỉ có trong dialog)"""
        try:
            # Table giờ chỉ có trong dialog, không cần refresh ở đây
            # Method này giữ lại để tương thích với code cũ
            pass
        except Exception as e:
            self.log(f"❌ Lỗi refresh characters table: {e}")
    
    def on_character_name_changed(self, item):
        """Xử lý khi user sửa tên character"""
        try:
            if item.column() != 1:  # Chỉ xử lý cột tên
                return
            
            row = item.row()
            old_name = item.data(Qt.UserRole)
            new_name = item.text().strip()
            
            if not new_name:
                # Tên rỗng → khôi phục tên cũ
                item.setText(old_name)
                QMessageBox.warning(self, "Cảnh báo", "Tên character không được để trống!")
                return
            
            if new_name == old_name:
                return  # Không thay đổi
            
            # Kiểm tra tên trùng
            if new_name in self.custom_characters and new_name != old_name:
                item.setText(old_name)
                QMessageBox.warning(self, "Cảnh báo", f"Tên '{new_name}' đã tồn tại!")
                return
            
            # Cập nhật dictionary
            if old_name in self.custom_characters:
                img_path = self.custom_characters.pop(old_name)
                self.custom_characters[new_name] = img_path
                
                # Cập nhật matching results nếu có
                for prompt_idx, matched_chars in self.character_matching_results.items():
                    if old_name in matched_chars:
                        matched_chars.remove(old_name)
                        if new_name not in matched_chars:
                            matched_chars.append(new_name)
                
                # Cập nhật UserRole
                item.setData(Qt.UserRole, new_name)
                
                self.log(f"✅ Đã đổi tên: {old_name} → {new_name}")
                
                # Refresh dialog nếu đang mở
                if hasattr(self, '_custom_dialog') and self._custom_dialog and self._custom_dialog.isVisible():
                    QTimer.singleShot(0, lambda: self._custom_dialog.refresh_characters_table())
                    if self.character_matching_results:
                        QTimer.singleShot(0, lambda: self._custom_dialog.refresh_matching_summary())
        except Exception as e:
            self.log(f"❌ Lỗi đổi tên character: {e}")
    
    def on_delete_character(self, char_name):
        """Xóa character"""
        try:
            reply = QMessageBox.question(
                self,
                "Xác nhận",
                f"Bạn có chắc muốn xóa nhân vật '{char_name}'?",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No
            )
            
            if reply == QMessageBox.Yes:
                # Xóa khỏi dictionary
                if char_name in self.custom_characters:
                    del self.custom_characters[char_name]
                
                # Xóa khỏi matching results
                for prompt_idx, matched_chars in list(self.character_matching_results.items()):
                    if char_name in matched_chars:
                        matched_chars.remove(char_name)
                        if not matched_chars:
                            # Nếu prompt không còn nhân vật nào, có thể xóa hoặc giữ lại
                            pass
                
                # Refresh dialog nếu đang mở
                if hasattr(self, '_custom_dialog') and self._custom_dialog and self._custom_dialog.isVisible():
                    QTimer.singleShot(0, lambda: self._custom_dialog.refresh_characters_table())
                    if self.character_matching_results:
                        QTimer.singleShot(0, lambda: self._custom_dialog.refresh_matching_summary())
                
                self.log(f"✅ Đã xóa nhân vật: {char_name}")
        except Exception as e:
            self.log(f"❌ Lỗi xóa character: {e}")
    
