    # ===== REWRITE TAB HANDLERS =====
    
    def _rewrite_log(self, message: str):
        """Log message to Rewrite tab log - THREAD-SAFE using Signal"""
        try:
            from datetime import datetime
            timestamp = datetime.now().strftime("%H:%M:%S")
            log_msg = f"[{timestamp}] {message}\n"
            
            # Always print to console for debugging
            print(f"Rewrite Log: {log_msg.strip()}")
            
            # Use Signal for thread-safe logging
            if hasattr(self, 'signals') and self.signals:
                self.signals.rewrite_log_message.emit(log_msg)
            else:
                print(f"⚠️ signals not found!")
        except Exception as e:
            print(f"Rewrite log error: {e}")
            import traceback
            traceback.print_exc()
    
    def _handle_rewrite_log_message(self, log_msg: str):
        """Handle rewrite log message from signal - RUNS IN MAIN THREAD"""
        try:
            if hasattr(self, 'txt_rewrite_log') and self.txt_rewrite_log:
                self.txt_rewrite_log.append(log_msg)
                # Auto-scroll to bottom
                cursor = self.txt_rewrite_log.textCursor()
                cursor.movePosition(cursor.MoveOperation.End)
                self.txt_rewrite_log.setTextCursor(cursor)
        except Exception as e:
            print(f"Handle rewrite log error: {e}")
    
