    def on_rewrite_get_subtitle(self):
        """Get subtitle from video using NoteGPT API - CLONED từ gui_app.py"""
        if self.rewrite_processing:
            QMessageBox.warning(self, "Cảnh báo", "Đang xử lý, vui lòng chờ...")
            return
        
        # ✅ Validate API key (Bắt buộc)
