    def on_sync_view_character_image(self, index):
        """View character image on double-click"""
        try:
            row = index.row()
            if row < 0:
                return
            
            char_item = self.sync_character_tree.item(row, 0)
            if not char_item:
                return
            
            char_name = char_item.text()
            
            # Tìm ảnh của character
            image_path = None
            if hasattr(self, 'character_images') and self.character_images:
                image_path = self.character_images.get(char_name)
            
            if not image_path or not Path(image_path).exists():
                QMessageBox.information(
                    self, "Thông báo",
                    f"Character '{char_name}' chưa có ảnh.\n"
                    "Vui lòng upload hoặc generate ảnh trước."
                )
                return
            
            # Hiển thị ảnh trong dialog
            dialog = QDialog(self)
            dialog.setWindowTitle(f"🖼️ Ảnh Character: {char_name}")
            dialog.setModal(True)
            
            # Set dialog size
            screen = QApplication.primaryScreen().geometry()
            dialog_width = min(800, int(screen.width() * 0.8))
            dialog_height = min(600, int(screen.height() * 0.8))
            dialog.setMinimumSize(dialog_width, dialog_height)
            dialog.resize(dialog_width, dialog_height)
            
            layout = QVBoxLayout(dialog)
            layout.setContentsMargins(10, 10, 10, 10)
            layout.setSpacing(10)
            
            # Character name
            name_label = QLabel(f"Character: {char_name}")
            name_label.setStyleSheet("font-size: 14pt; font-weight: bold; color: #0078d4;")
            layout.addWidget(name_label)
            
            # Image display
            image_label = QLabel()
            pixmap = QPixmap(str(image_path))
            if not pixmap.isNull():
                # Scale image to fit dialog while maintaining aspect ratio
                scaled_pixmap = pixmap.scaled(
                    dialog_width - 40, dialog_height - 100,
                    Qt.AspectRatioMode.KeepAspectRatio,
                    Qt.TransformationMode.SmoothTransformation
                )
                image_label.setPixmap(scaled_pixmap)
                image_label.setAlignment(Qt.AlignCenter)
            else:
                image_label.setText("Không thể tải ảnh")
                image_label.setStyleSheet("color: red; font-size: 12pt;")
            
            layout.addWidget(image_label)
            
            # Image path info
            path_label = QLabel(f"Path: {image_path}")
            path_label.setStyleSheet("font-size: 9pt; color: #666;")
            path_label.setWordWrap(True)
            layout.addWidget(path_label)
            
            # Close button
            btn_close = QPushButton("Đóng")
            btn_close.clicked.connect(dialog.accept)
            layout.addWidget(btn_close)
            
            dialog.exec()
            
        except Exception as e:
            self.sync_log(f"❌ Lỗi xem ảnh: {e}\n")
            import traceback
            self.sync_log(traceback.format_exc()[:300] + "\n")
    
    def _handle_sync_log_message(self, message):
        """Handle sync log message from signal - RUNS IN MAIN THREAD"""
        try:
            if hasattr(self, 'txt_sync_result') and self.txt_sync_result is not None:
                # Try append first
                try:
                    self.txt_sync_result.append(message)
                except:
                    # Fallback to setPlainText if append fails
                    try:
                        current = self.txt_sync_result.toPlainText()
                        self.txt_sync_result.setPlainText(current + "\n" + message)
                    except:
                        pass
                
                # Auto-scroll to bottom
                try:
                    cursor = self.txt_sync_result.textCursor()
                    cursor.movePosition(cursor.MoveOperation.End)
                    self.txt_sync_result.setTextCursor(cursor)
                except:
                    pass
        except Exception:
            # Last resort: print to console
            print(f"[SYNC LOG HANDLER ERROR] {message}")
    
    def _handle_update_progress_bar(self, row_index, percent):
        """Handle update progress bar from signal - RUNS IN MAIN THREAD"""
        try:
            if hasattr(self, 'prompts_table') and self.prompts_table is not None:
                if row_index < self.prompts_table.rowCount():
                    progress_bar = self.prompts_table.cellWidget(row_index, 2)
                    if progress_bar and isinstance(progress_bar, QProgressBar):
                        progress_bar.setValue(percent)
                        progress_bar.setFormat(f"{percent}%")
                        
                        # ✅ GRADIENT MÀU: Vàng → Cam → Xanh dương → Xanh lá cây
                        if percent == 0:
                            chunk_color = "#FFD700"  # Vàng (Gold)
                        elif percent < 25:
                            chunk_color = "#FFC107"  # Vàng (Amber)
                        elif percent < 50:
                            chunk_color = "#FF9800"  # Cam (Orange)
                        elif percent < 75:
                            chunk_color = "#2196F3"  # Xanh dương (Blue)
                        elif percent < 100:
                            chunk_color = "#4CAF50"  # Xanh lá cây (Green)
                        else:
                            chunk_color = "#43A047"  # Xanh lá cây đậm (Dark Green)
                        
                        # Update stylesheet
                        progress_bar.setStyleSheet(f"""
                            QProgressBar {{
                                border: 1px solid #BDBDBD;
                                border-radius: 3px;
                                text-align: center;
                                background-color: #F5F5F5;
                                font-weight: bold;
                                font-size: 10px;
                            }}
                            QProgressBar::chunk {{
                                background-color: {chunk_color};
                                border-radius: 2px;
                            }}
                        """)
        except Exception as e:
            # Silently ignore errors
            pass
    
    def _handle_show_upload_dialog(self):
        """Handle show upload dialog from signal - RUNS IN MAIN THREAD"""
        try:
            # Delay một chút để đảm bảo notification đã hiển thị trước
            from PySide6.QtCore import QTimer
            QTimer.singleShot(1500, lambda: self._show_character_upload_dialog(wait_for_completion=False))
        except Exception as e:
            self._sync_log_error(f"❌ Lỗi hiển thị upload dialog: {e}")
    
    def _handle_show_review_dialog(self):
        """Handle show review dialog from signal - RUNS IN MAIN THREAD"""
        try:
            if hasattr(self, '_review_prompts_data') and hasattr(self, '_review_outdir_text'):
                result = self._show_prompt_review_dialog(self._review_prompts_data, self._review_outdir_text)
                self._review_dialog_result = result
            else:
                self._review_dialog_result = True  # Continue if no data
        except Exception as e:
            self._sync_log_error(f"❌ Lỗi hiển thị review dialog: {e}")
            self._review_dialog_result = True  # Continue on error
    
    def _show_prompt_review_dialog(self, prompts_data, outdir_text):
        """Show dialog để xem lại và chỉnh sửa prompts + ảnh tham chiếu trước khi integrate"""
