    def _get_api_keys(self):
        """Get Gemini API keys - CHỈ dùng user keys, KHÔNG dùng DEFAULT_GEMINI_KEYS
            
        Yêu cầu user phải nhập API key của họ để sử dụng.
        """
        try:
            user_keys: List[str] = []
            
            if getattr(self, "gemini_api_keys", None):
                user_keys.extend([key.strip() for key in self.gemini_api_keys if key])
            
            if hasattr(self, 'txt_rewrite_gemini_key') and self.txt_rewrite_gemini_key:
                rewrite_text = self.txt_rewrite_gemini_key.text().strip()
                if rewrite_text:
                    user_keys.extend([line.strip() for line in rewrite_text.splitlines() if line.strip()])
            
            if hasattr(self, 'txt_sync_gemini_key') and self.txt_sync_gemini_key:
                sync_text = self.txt_sync_gemini_key.text().strip()
                if sync_text:
                    user_keys.extend([line.strip() for line in sync_text.splitlines() if line.strip()])
            
            if hasattr(self, 'integrate_gemini_api_keys') and self.integrate_gemini_api_keys:
                user_keys.extend([k for k in self.integrate_gemini_api_keys if k])
            
            # Loại bỏ trùng lặp nhưng giữ thứ tự
            seen = set()
            ordered_user_keys = []
            for key in user_keys:
                if key not in seen:
                    ordered_user_keys.append(key)
                    seen.add(key)
            
            # ✅ CHỈ trả về user keys, KHÔNG dùng default keys
            keys = ordered_user_keys
            
            if ordered_user_keys:
                msg = f"🔑 Sử dụng {len(ordered_user_keys)} user API key"
                if hasattr(self, '_rewrite_log'):
                    self._rewrite_log(msg)
                elif hasattr(self, 'sync_log'):
                    self.sync_log(msg + "\n")
            else:
                # Không có user keys - cảnh báo
                if hasattr(self, '_rewrite_log'):
                    self._rewrite_log("⚠️ Không có user API keys! Vui lòng nhập API key của bạn.")
                elif hasattr(self, 'sync_log'):
                    self.sync_log("⚠️ Không có user API keys! Vui lòng nhập API key của bạn.\n")
            
            return keys
        except Exception as e:
            if hasattr(self, '_rewrite_log'):
                self._rewrite_log(f"⚠️ Không lấy được API keys: {e}")
            elif hasattr(self, 'sync_log'):
                self.sync_log(f"⚠️ Không lấy được API keys: {e}\n")
            return []
    
    def get_gemini_api_keys(self) -> List[str]:
        """Public helper để lấy Gemini API keys cho các module khác"""
        try:
            return self._get_api_keys()
        except Exception as e:
            if hasattr(self, 'log'):
                self.log(f"⚠️ Lỗi lấy Gemini API keys: {e}")
            return []
    
    def _get_gemini_keys_file_path(self) -> str:
        """Trả về đường dẫn file lưu Gemini keys"""
        from pathlib import Path
        # Lưu vào thư mục GetCookieVeo3 (nơi lưu config)
        app_data_dir = Path.home() / "GetCookieVeo3"
        app_data_dir.mkdir(parents=True, exist_ok=True)
        return str(app_data_dir / "gemini_keys.json")
    
    def _load_gemini_keys_from_file(self):
        """Load Gemini API keys từ file local JSON"""
        try:
            import json
            file_path = self._get_gemini_keys_file_path()
            from pathlib import Path
            if Path(file_path).exists():
                with open(file_path, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                    keys = data.get('gemini_api_keys', [])
                    if keys and isinstance(keys, list):
                        self.gemini_api_keys = [k for k in keys if k and k.strip().startswith('AIza')]
                        # Cũng cập nhật integrate_gemini_api_keys
                        if hasattr(self, 'integrate_gemini_api_keys'):
                            self.integrate_gemini_api_keys = self.gemini_api_keys.copy()
                        print(f"✅ Đã load {len(self.gemini_api_keys)} Gemini API keys từ file")
        except Exception as e:
            print(f"⚠️ Không thể load Gemini keys từ file: {e}")
            self.gemini_api_keys = []
    
    def _save_gemini_keys_to_file(self):
        """Lưu Gemini API keys vào file local JSON"""
        try:
            import json
            file_path = self._get_gemini_keys_file_path()
            data = {'gemini_api_keys': self.gemini_api_keys}
            with open(file_path, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2)
            print(f"✅ Đã lưu {len(self.gemini_api_keys)} Gemini API keys vào file")
            return True
        except Exception as e:
            print(f"❌ Lỗi lưu Gemini keys: {e}")
            return False
    
    def _clear_old_workflow_data(self):
        """Clear old workflow data - THREAD-SAFE UI UPDATES"""
        try:
            import shutil
            self.sync_log("🧹 Đang XÓA TRIỆT ĐỂ TOÀN BỘ cache...\n")
            
            # Clear in-memory data (thread-safe)
            self.character_images = {}
            self.extracted_characters = []
            self.sync_video_media_ids = []
            self.character_image_media_ids = {}
            
            # ✅ XÓA TRIỆT ĐỂ INTEGRATE_VIDEOS VÀ CHARACTER_IMAGES FOLDERS
            try:
                outdir_text = ""
                if hasattr(self, 'txt_sync_outdir') and self.txt_sync_outdir:
                    outdir_text = self.txt_sync_outdir.text().strip()
                
                if outdir_text:
                    output_dir = Path(outdir_text)
                    
                    # Xóa integrate_videos folder
                    integrate_videos_dir = output_dir / "integrate_videos"
                    if integrate_videos_dir.exists():
                        # Xóa tất cả video files
                        video_files = list(integrate_videos_dir.glob("*.mp4"))
                        for vf in video_files:
                            try:
                                vf.unlink()
                                self.sync_log(f"🗑️ Xóa video cũ: {vf.name}\n")
                            except Exception as e:
                                pass
                        
                        self.sync_log(f"✅ Đã xóa {len(video_files)} video files cũ\n")
                    
                    # ✅ XÓA character_images folder
                    char_images_dir = output_dir / "character_images"
                    if char_images_dir.exists():
                        # Xóa tất cả image files
                        image_files = list(char_images_dir.glob("*"))
                        for img_file in image_files:
                            try:
                                img_file.unlink()
                                self.sync_log(f"🗑️ Xóa character image cũ: {img_file.name}\n")
                            except Exception as e:
                                pass
                        
                        self.sync_log(f"✅ Đã xóa {len(image_files)} character image files cũ\n")
            except Exception as e:
                self.sync_log(f"⚠️ Lỗi xóa files: {e}\n")
            
            # Clear script hash để force fresh detection
            self._last_script_hash = None
            self.sync_log("🗑️ Reset script hash tracker\n")
            
            # ✅ UI UPDATE: Use QTimer để clear character tree từ main thread
            def clear_character_tree_safe():
                try:
                    if hasattr(self, 'sync_character_tree') and self.sync_character_tree is not None:
                        self.sync_character_tree.setRowCount(0)
                except Exception as e:
                    # Silently ignore UI errors
                    pass
            
            # Schedule UI update từ main thread
            QTimer.singleShot(0, clear_character_tree_safe)
            
            self.sync_log("✅ Đã xóa cache\n")
        except Exception as e:
            self.sync_log(f"❌ Lỗi clear cache: {e}\n")
    
    def _update_character_tree(self):
        """Update character tree - SIMPLIFIED THREAD-SAFE VERSION"""
        try:
            # ✅ CHẠY NGAY TRONG MAIN THREAD (được gọi qua QTimer.singleShot)
            # Không cần complex locking vì QTimer đảm bảo main thread execution
            
            # Check if widget exists
            if not hasattr(self, 'sync_character_tree') or self.sync_character_tree is None:
                self.sync_log("⚠️ Character tree widget không tồn tại\n")
                return
            
            # ✅ SIMPLE FLAG CHECK thay vì complex locking (tránh deadlock)
            if getattr(self, '_updating_tree', False):
                return  # Skip if already updating
                
                self._updating_tree = True
                
            try:
                # Copy data để tránh changes during update
                characters_copy = list(self.extracted_characters) if hasattr(self, 'extracted_characters') and self.extracted_characters else []
                images_copy = dict(self.character_images) if hasattr(self, 'character_images') and self.character_images else {}
                sources_copy = dict(self.character_image_sources) if hasattr(self, 'character_image_sources') and self.character_image_sources else {}
                
                self.sync_log(f"🔍 Updating character tree: {len(characters_copy)} characters, {len(images_copy)} images\n")
                
                # Clear existing items - SAFE vì chỉ chạy trong main thread
                self.sync_character_tree.setRowCount(0)
                
                # Add characters to tree
                for char in characters_copy:
                    try:
                        name = char.get("name", "Unknown")
                        description = char.get("description", "No description")
                        if len(description) > 50:
                            description = description[:50] + "..."
                        
                        # Check if we have image for this character
                        has_image = name in images_copy
                        
                        # Check if image has been uploaded to Google Labs (has media_id)
                        has_media_id = False
                        if has_image:
                            img_path = images_copy.get(name)
                            if img_path:
                                img_path_abs = str(Path(img_path).resolve())
                                if hasattr(self, 'character_image_media_ids') and self.character_image_media_ids:
                                    has_media_id = img_path_abs in self.character_image_media_ids
                        
                        # Update status based on image and media_id
                        if has_media_id:
                            image_status = "✅ Ready"  # Đã có media_id
                        elif has_image:
                            image_status = "📤 Uploading"  # Có ảnh nhưng chưa upload
                        else:
                            image_status = "⏳ Pending"  # Chưa có ảnh
                        
                        # Determine image source
                        image_source = sources_copy.get(name, "N/A")
                        if has_image:
                            if image_source == "uploaded":
                                image_source = "📤 Uploaded"
                            elif image_source == "generated":
                                image_source = "🤖 Generated"
                            else:
                                image_source = "🤖 Generated"
                        else:
                            image_source = "-"
                        
                        row = self.sync_character_tree.rowCount()
                        self.sync_character_tree.insertRow(row)
                        self.sync_character_tree.setItem(row, 0, QTableWidgetItem(name))
                        self.sync_character_tree.setItem(row, 1, QTableWidgetItem(description))
                        self.sync_character_tree.setItem(row, 2, QTableWidgetItem("✅" if has_image else "⏳"))
                        self.sync_character_tree.setItem(row, 3, QTableWidgetItem(image_status))
                        self.sync_character_tree.setItem(row, 4, QTableWidgetItem(image_source))
                    except Exception as e:
                        # Continue với character tiếp theo
                        self.sync_log(f"⚠️ Lỗi thêm character vào tree: {e}\n")
                        continue
                
                self.sync_log(f"✅ Đã update character tree với {self.sync_character_tree.rowCount()} rows\n")
                
            except Exception as e:
                self.sync_log(f"❌ Lỗi update tree: {e}\n")
            finally:
                self._updating_tree = False
                
        except Exception as e:
            # ✅ SIMPLE ERROR HANDLING - không complex cleanup
            self._updating_tree = False
            # Silently log to prevent cascade errors
            try:
                self.sync_log(f"❌ Tree update error: {e}\n")
            except:
                print(f"❌ Tree update error: {e}")  # Fallback to console
    
