            upload_frame.setMinimumHeight(100)
            upload_layout = QVBoxLayout(upload_frame)
            
            upload_title = QLabel("📤 Tự Upload Ảnh")
            upload_title.setStyleSheet("font-size: 13pt; font-weight: bold; color: #0078d4;")
            upload_layout.addWidget(upload_title)
            
            upload_desc = QLabel("Bạn sẽ tự chọn và upload ảnh cho từng nhân vật")
            upload_desc.setStyleSheet("font-size: 10pt; color: #666;")
            upload_layout.addWidget(upload_desc)
            
            btn_upload = QPushButton("Chọn phương thức này")
            btn_upload.setStyleSheet("background-color: #0078d4; color: white; padding: 8px; border-radius: 3px;")
            btn_upload.clicked.connect(on_manual_upload)
            upload_layout.addWidget(btn_upload)
            
