            # Process events to ensure UI is ready
            from PySide6.QtWidgets import QApplication
            QApplication.processEvents()
            
            dialog.raise_()
            dialog.activateWindow()
            dialog.show()
            
            # Process events again to ensure dialog is shown
            QApplication.processEvents()
            
            # Small delay to ensure dialog is fully rendered
            import time
            time.sleep(0.2)
            QApplication.processEvents()
            
            # Execute dialog (blocking)
            self._sync_log_info("🔔 Đang chờ user chọn...")
            result = dialog.exec()
