            # Store prompts editors: {row: QTextEdit}
            prompt_editors = {}  # {row: editor}
            # Cache edits theo file: {file_stem: {global_index: prompt_text}}
            edited_cache: Dict[str, Dict[int, str]] = {}
            current_file_stem = [None]  # mutable holder

            def _save_current_file_edits():
                """Lưu các prompt đang hiển thị vào cache/failed_tasks_data trước khi chuyển file"""
                if current_file_stem[0] is None:
                    return
                file_stem = current_file_stem[0]
                if file_stem not in failed_tasks_data:
                    return
                cache_for_file = edited_cache.setdefault(file_stem, {})

                # Cập nhật từ bảng hiện tại
                for row_idx in range(prompts_table.rowCount()):
                    file_line_item = prompts_table.item(row_idx, 1)
                    if not file_line_item:
                        continue
                    global_idx = file_line_item.data(Qt.UserRole)
                    if global_idx is None:
                        continue
                    editor = prompt_editors.get(row_idx)
                    if not editor:
                        continue
                    new_prompt = editor.toPlainText().strip()
                    if not new_prompt:
                        continue
                    cache_for_file[global_idx] = new_prompt
                    # Cập nhật thẳng vào failed_tasks_data
                    for task in failed_tasks_data[file_stem]:
                        if task['global_index'] == global_idx:
                            task['prompt'] = new_prompt
                            break
            
            def on_file_clicked(row, column):
                """Khi click vào file, hiển thị prompts lỗi của file đó"""
