                prompts_table.setRowCount(0)
                prompt_editors.clear()
                
                # Populate prompts table
                failed_tasks = failed_tasks_data[file_stem]
                cache_for_file = edited_cache.get(file_stem, {})
                for idx, task in enumerate(failed_tasks, 1):
                    row_idx = prompts_table.rowCount()
